# mix-up (u4) đã có thẻ → chỉ nhắc.
theory = (
 H("A", "Dialogues commenting on situations", "Hội thoại bình luận về tình huống")
 + P("Maya wishes she could <b>get out of</b> a cold bike ride (avoid it with an excuse). Oscar always <b>mixes up</b> identical twins Flora and Florence (thinks one is the other); Stan <b>muddles</b> them <b>up</b> too (confuses them in his mind). Megan says Bethany thinks the world <b>revolves around</b> her (she is the centre of everything). John’s team has been <b>running up against</b> problems (starting to experience them); Leah says another problem always <b>crops up</b> (appears unexpectedly) and she can’t <b>bank on</b> things <b>turning out</b> well (depend on things happening in a good way).",
     "Maya ước <b>get out of</b> chuyến đạp xe giữa trời lạnh (kiếm cớ né). Oscar luôn <b>mixes up</b> cặp sinh đôi Flora và Florence (nhầm người này là người kia); Stan cũng <b>muddles</b> họ <b>up</b> (lẫn lộn trong đầu). Megan nói Bethany nghĩ cả thế giới <b>revolves around</b> cô ta (là trung tâm). Nhóm của John đang <b>running up against</b> nhiều vấn đề (bắt đầu gặp phải); Leah nói hết chuyện này lại <b>crops up</b> chuyện khác (bất ngờ nảy sinh) và cô không dám <b>bank on</b> mọi việc <b>turning out</b> tốt đẹp (trông chờ kết quả tốt).")
 + H("B", "An island revolution", "Cuộc cách mạng trên đảo")
 + P("Milly says a small <b>mix-up</b> of orders (card in Unit 4) has become a drama; Tom tells her to <b>rise above</b> it (not let it upset her) and <b>back off</b> (stop being involved). A news report: holidaymakers <b>caught up</b> in a revolution on St Maria (involved without wanting to be) have come home. The situation <b>hotted up</b> (became more exciting and active – compare <i>heat up</i> for food, Units 26 and 60) when rebels seized the palace; the tourists were <b>thrown together</b> in a large hotel (forced to be together) until things <b>calmed down</b> (became more peaceful).",
     "Milly kể một <b>mix-up</b> nhỏ về đơn hàng (đã có thẻ ở bài 4) bị làm to chuyện; Tom bảo cô <b>rise above</b> nó (đừng để bị ảnh hưởng) và <b>back off</b> (rút ra, để người khác lo). Một bản tin: du khách <b>caught up</b> trong cuộc cách mạng ở đảo St Maria (bị cuốn vào) đã về nước. Tình hình <b>hotted up</b> (căng lên, sôi động – so sánh <i>heat up</i> dùng cho đồ ăn, bài 26 và 60) khi phiến quân chiếm phủ tổng thống; du khách bị <b>thrown together</b> trong một khách sạn lớn (buộc phải ở cùng nhau) đến khi tình hình <b>calmed down</b> (yên ổn lại).")
 + NOTE("<b>Over to you</b>: pick five of these verbs and write about real situations from your own recent life.", "<b>Over to you</b>: chọn năm động từ trong bài và đặt câu về những tình huống bạn gặp gần đây.")
)
